    for (int i = 1; i <= 162; i++) { // corrected loop limit
        long[][][][] dp = new long[s + 1][2][i + 1][i];
        dp[0][1][0][0] = 1;
        for (int j = 0; j < s; j++) {
            int c = Character.getNumericValue(cs[j]);
            for (int j2 = 0; j2 < 2; j2++) {
                for (int k = 0; k <= i; k++) {
                    for (int k2 = 0; k2 < i; k2++) {
                        long pre = dp[j][j2][k][k2];
                        if (pre == 0) continue;
                        for (int l = 0; l < 10; l++) {
                            int nj2 = j2;
                            int nk = k + l;
                            int nk2 = (k2 * 10 + l) % i;
